# 23t_rdbyi_items.R  As 23_rdbyi_items.R after 22t (PSP thinning removals censored; benchmark horizons stop before the first removal year of a thinned installation). After 22t_rdbyi_final.R (system S1 + E4r + E6r with SDImax from BYI and origin): (1) benchmark, with S1 out of fold; (2) 200-year
# gates; (3) Monte Carlo 90% bands at 20, 40, 100 years for the six scenarios, without and with a plot-level deviation of SDImax about S1;
# (4) coverage at each benchmark plot's longest horizon; (5) Table 4 trajectories and Figs. 3 to 5; (6) workbook grid. No model fitting except S1 by fold.
# Draws: one joint bootstrap row (S1, E4r, E6r refitted together), plot increment multiplier (lognormal, sd tau), tree-year variation (sd sigma g^delta),
# plot mortality multiplier (gamma, variance phi); in the "site" variant also ln(SDImax) + N(0, residual sd of S1). Height parameters at their estimates.
suppressMessages({library(data.table); library(ggplot2); library(patchwork)}); setwd("~/jobs/koa_final_eq_20261110"); source("scripts/utils.R"); source("release/koa_step.R"); options(width = 230)
ND <- as.integer(Sys.getenv("KOA_NDRAW", "500")); NDc <- as.integer(Sys.getenv("KOA_NDRAW_COV", "300")); NC <- as.integer(Sys.getenv("KOA_CORES", "6")); RNGkind("L'Ecuyer-CMRG"); set.seed(20261118); dir.create("ms_rdbyi2", showWarnings = FALSE)
f <- readRDS("frames/frames.rds"); tr <- f$tr
th <- fread("~/jobs/koa_v105final_20261103/inputs/psp_origin_thinning_2026-09-16_DATA.csv"); REM <- th[removal_t1_years != "" & !is.na(removal_t1_years), .(yr = as.integer(unlist(strsplit(as.character(removal_t1_years), ";")))), by = .(Data, Install = as.character(Install))]
flagrem <- function(x, strict) { x <- copy(x); x[, rid__ := .I]; k <- merge(x[, .(rid__, Data, Install = as.character(Install), Measure, e_Measure)], REM, by = c("Data", "Install"), allow.cartesian = TRUE); k <- if (strict) k[yr > Measure & yr < e_Measure] else k[yr > Measure & yr <= e_Measure]; x[, rem__ := rid__ %in% k$rid__]; x }   # PSP thinning removals (psp_origin_thinning_2026-09-16_DATA.csv): mortality intervals ending in or spanning a removal year are censored; increment intervals with a removal year strictly inside are dropped
 cf <- koa_read_coef("release/koa_final_equations.csv"); FT <- readRDS("out/rdbyi2_fits.rds"); BT <- readRDS("out/rdbyi2_boot.rds"); K <- BT$K; bs <- FT$bs; bg <- FT$bg; bm <- FT$bm; E2 <- readRDS("out/E2_height_cr3.rds"); bH <- E2$boot[complete.cases(E2$boot), , drop = FALSE]
s1p <- function(b, lbyi, pl) exp(b[[1]] + b[[2]] * lbyi + b[[3]] * pl); kS <- 1:3; kG <- 4:9; kM <- 10:17; cat("bootstrap rows:", nrow(K), "; S1 residual sd (ln scale):", round(FT$s1_resid_sd, 3), "; sigma", round(FT$sigma, 4), " tau", round(FT$tau, 4), " delta", round(FT$delta, 4), " phi", round(FT$phi, 4), "\n")
xm <- function(S, BAL, BA, SDI, sm, byi, pl) cbind(1, log(S + 1), S, BAL / pmax(BA, 1e-6) * SDI / sm, log(byi), pl)
simx <- function(dbh, ht, ex, byi, pl, years, sm, bg. = bg, bm. = bm, R = 1, sig = 0, dl = 0, ph = 1) { out <- matrix(NA_real_, years + 1, 7, dimnames = list(NULL, c("BA", "TPH", "QMD", "HT", "VOL", "RD", "SDI")))
  for (y in 0:years) { s <- koa_stand(dbh, ht, ex); out[y + 1, ] <- c(s$BA, s$TPH, s$QMD, s$HT, 0.40 * s$BA * s$HT, s$SDI / sm, s$SDI); if (y == years) break
    bal <- koa_bal(dbh, s$ba); rd <- s$SDI / sm; g <- as.numeric(exp(xm(dbh, bal, s$BA, s$SDI, sm, byi, pl) %*% bg.)) * R; if (sig > 0) { s2 <- log(1 + (sig * pmax(g, 0.01)^(dl - 1))^2); g <- g * exp(rnorm(length(g), 0, sqrt(s2)) - s2 / 2) }
    pm <- 1 - exp(-ph * exp(as.numeric(cbind(1, log(dbh + 1), dbh, dbh^2, bal, log(max(rd, 0.001)), log(byi), pl) %*% bm.))); ht <- ht + koa_height(dbh + g, cf) - koa_height(dbh, cf); dbh <- dbh + g; ex <- ex * (1 - pm) }
  out }
draw <- function(lbyi, pl, site) { k <- K[sample(nrow(K), 1), ]; t2 <- log(1 + FT$tau^2); list(sm = s1p(k[kS], lbyi, pl) * (if (site) exp(rnorm(1, 0, FT$s1_resid_sd)) else 1), bg = k[kG], bm = k[kM], R = exp(rnorm(1, 0, sqrt(t2)) - t2 / 2), ph = if (FT$phi > 0) rgamma(1, 1 / FT$phi, 1 / FT$phi) else 1) }
onedraw <- function(dbh, ht, ex, byi, pl, years, site) { q <- draw(log(byi), pl, site); simx(dbh, ht, ex, byi, pl, years, q$sm, q$bg, q$bm, q$R, FT$sigma, FT$delta, q$ph) }
# ---- (1) benchmark ----
J <- "~/jobs/koa_brms_sdimax_20261102/out/"; sx <- fread(paste0(J, "plot_sdimax_rilong.csv")); sx[, ID := as.character(ID)]; P <- unique(tr[, .(pid, Data, Install, Plot = as.character(Plot), planted, BYI)]); P[, key := ifelse(Data == "FIA", as.character(Install), pid)]
P <- merge(P, sx[, .(key = ID, ID1 = ID)], by = "key", all.x = TRUE); k2 <- sx[, .(Data, Plot = as.character(Plot), ID2 = ID)][, if (.N == 1) .SD, by = .(Data, Plot)]; P <- merge(P, k2, by = c("Data", "Plot"), all.x = TRUE); P[, ID := ifelse(!is.na(ID1), ID1, ID2)]
P <- merge(P, sx[, .(ID, smax = SDImax_mean, lo = `SDImax_q2.5`, hi = `SDImax_q97.5`)], by = "ID", all.x = TRUE); P[, `:=`(inst = paste(Data, Install), lbyi = log(BYI), ls = log(smax), w = 1 / pmax((log(hi) - log(lo)) / 3.92, 0.05)^2)]; P <- merge(P, make_folds(P), by = "inst"); M <- P[!is.na(smax)]
o <- rep(NA_real_, nrow(P)); for (k in sort(unique(P$fold))) o[P$fold == k] <- s1p(coef(lm(ls ~ lbyi + planted, data = M[fold != k], weights = w)), P$lbyi[P$fold == k], P$planted[P$fold == k]); SMO <- setNames(o, P$pid)
startv <- tr[Status == "live" & !is.na(DBH) & DBH > 0, .(n = .N), by = .(pid, Measure)][n >= 5][, .SD[which.min(Measure)], by = pid]
plotinfo <- function(i) { p <- startv$pid[i]; m0 <- startv$Measure[i]; L <- tr[pid == p & Measure == m0 & Status == "live" & !is.na(DBH) & DBH > 0]; L[is.na(HT) | HT < 1.37, HT := koa_height(DBH, cf)]; later <- sort(unique(tr[pid == p & Measure > m0, Measure])); if (nrow(f$srep[pid == p & Measure >= m0])) later <- later[later <= min(f$srep[pid == p & Measure >= m0, Measure])]
  ry <- REM[Data == L$Data[1] & Install == as.character(L$Install[1]) & yr > m0, yr]; if (length(ry)) later <- later[later < min(ry)]
  if (!length(later)) return(NULL); obs <- rbindlist(lapply(later, function(m1) { ob <- merge(tr[pid == p & Measure == m1 & uid %in% L$uid & Status == "live", .(uid, DBH_c)], L[, .(uid, EXPF_c)], by = "uid"); if (!nrow(ob)) return(NULL); data.table(h = m1 - m0, o_surv = sum(ob$EXPF_c) / sum(L$EXPF_c), o_qmd = sqrt(sum(ob$DBH_c^2 * ob$EXPF_c) / sum(ob$EXPF_c)), o_ba = sum(0.00007854 * ob$DBH_c^2 * ob$EXPF_c)) }))
  if (!nrow(obs)) return(NULL); list(p = p, L = L, pl = L$planted[1], byi = L$BYI[1], obs = obs, n0 = nrow(L), N0 = sum(L$EXPF_c)) }
PI <- Filter(Negate(is.null), lapply(seq_len(nrow(startv)), plotinfo))
bench <- rbindlist(lapply(PI, function(x) { z <- simx(x$L$DBH, x$L$HT, x$L$EXPF_c, x$byi, x$pl, max(x$obs$h), SMO[[x$p]]); cbind(pid = x$p, planted = x$pl, x$obs, p_surv = z[x$obs$h + 1, "TPH"] / x$N0, p_qmd = z[x$obs$h + 1, "QMD"], p_ba = z[x$obs$h + 1, "BA"]) }))
sm1 <- function(b) b[, .(n = .N, plots = uniqueN(pid), surv_bias = round(mean(o_surv - p_surv), 3), surv_rmse = round(sqrt(mean((o_surv - p_surv)^2)), 3), qmd_bias = round(mean(o_qmd - p_qmd), 2), qmd_rmse = round(sqrt(mean((o_qmd - p_qmd)^2)), 2), ba_bias = round(mean(o_ba - p_ba), 2), ba_rmse = round(sqrt(mean((o_ba - p_ba)^2)), 2))]
cat("\n(1) benchmark, S1 out of fold (earlier systems: own SDImax 0.177, 3.89, 6.70; 742 0.217, 3.99, 10.76)\n"); print(cbind(set = "all", sm1(bench))); print(bench[, sm1(.SD), by = planted]); print(cbind(set = "horizon 10 yr or more", sm1(bench[h >= 10])))
last <- bench[, .SD[which.max(h)], by = pid]; cols <- c("bias_rel", "slope", "b1_lo", "b1_hi", "pass_int", "pass_slope"); cat("equivalence at each plot's longest horizon (25% region, convention)\n")
print(rbindlist(lapply(list(all = last, planted = last[planted == 1], natural = last[planted == 0]), function(x) rbind(cbind(var = "survival", equiv_boot(x$o_surv, x$p_surv, x$pid)[, ..cols]), cbind(var = "QMD", equiv_boot(x$o_qmd, x$p_qmd, x$pid)[, ..cols]), cbind(var = "BA", equiv_boot(x$o_ba, x$p_ba, x$pid)[, ..cols]))), idcol = "set"))
