# ---- (2) gates ----
vis <- tr[Status == "live" & !is.na(DBH) & DBH > 0, .(n = .N, q = sqrt(sum(DBH^2 * EXPF_c) / sum(EXPF_c))), by = .(pid, Measure, planted)][n >= 10]; byiq <- unique(tr[, .(pid, planted, BYI)])[, .(lo = quantile(BYI, .1), md = quantile(BYI, .5), hi = quantile(BYI, .9)), by = planted]; pick <- vis[, .SD[which.min(abs(q - quantile(q, 0.25)))], by = planted]
getL <- function(p) { pv <- pick[planted == p]; L <- tr[pid == pv$pid & Measure == pv$Measure & Status == "live" & !is.na(DBH) & DBH > 0]; L[is.na(HT) | HT < 1.37, HT := koa_height(DBH, cf)]; L }
SC <- CJ(planted = c(0, 1), level = c("lo", "md", "hi"), sorted = FALSE); SC[, byi := mapply(function(p, l) byiq[planted == p][[l]], planted, level)]; SC[, sdimax := s1p(bs, log(byi), planted)]
S <- rbindlist(lapply(seq_len(nrow(SC)), function(i) { L <- getL(SC$planted[i]); cbind(planted = SC$planted[i], level = SC$level[i], byi = SC$byi[i], sdimax = SC$sdimax[i], year = 0:200, as.data.table(simx(L$DBH, L$HT, L$EXPF_c, SC$byi[i], SC$planted[i], 200, SC$sdimax[i]))) }))
L1 <- getL(1); bmd <- byiq[planted == 1, md]; DS <- rbindlist(lapply(c(300, 600, 1200, 2400), function(n0) cbind(n0 = n0, year = 0:100, as.data.table(simx(L1$DBH, L1$HT, L1$EXPF_c * n0 / sum(L1$EXPF_c), bmd, 1, 100, s1p(bs, log(bmd), 1))))))
w <- dcast(S, planted + year ~ level, value.var = c("BA", "QMD", "TPH")); LIM <- c(`0` = 1.2 * 1410.063, `1` = 1.2 * 1135.136)
gates <- data.table(site_to_100 = w[year >= 1 & year <= 100, all(BA_lo <= BA_md + 1e-9 & BA_md <= BA_hi + 1e-9 & QMD_lo <= QMD_md + 1e-9 & QMD_md <= QMD_hi + 1e-9)], sdi_lim = S[, max(SDI) <= LIM[as.character(planted[1])], by = planted][, all(V1)], ba200 = S[year == 200, all(BA <= 89.6)],
  no_rise = S[, SDI[year == 200] / SDI[year == 150] <= 1.05, by = .(planted, level)][, all(V1)], sukachev = w[year %in% c(40, 100), all(TPH_md <= TPH_lo * 1.02 & TPH_hi <= TPH_md * 1.02)], yield_dens = DS[year %in% c(20, 40, 100), all(diff(BA[order(n0)]) >= -1e-9), by = year][, all(V1)])
cat("\n(2) 200-year runs, SDImax from S1\n"); print(S[year %in% c(20, 40, 60, 100, 150, 200), .(planted, level, byi = round(byi), sdimax = round(sdimax), year, BA = round(BA, 1), TPH = round(TPH), QMD = round(QMD, 1), SDI = round(SDI), RD = round(RD, 2), HT = round(HT, 1))])
print(S[, .(sdi_max = round(max(SDI)), rd_max = round(max(RD), 2), ba_max = round(max(BA), 1), ba_peak_year = year[which.max(BA)], late_slope = round(coef(lm(log(TPH[year >= 100]) ~ log(QMD[year >= 100])))[[2]], 2)), by = .(planted, level)])
cat("first year basal area is out of site order: natural", w[planted == 0 & year >= 1 & !(BA_lo <= BA_md + 1e-9 & BA_md <= BA_hi + 1e-9), min(year)], " planted", w[planted == 1 & year >= 1 & !(BA_lo <= BA_md + 1e-9 & BA_md <= BA_hi + 1e-9), min(year)], "\ndensity series, planted, median BYI (BA at 20, 40, 100 yr):\n"); print(dcast(DS[year %in% c(20, 40, 100)], n0 ~ year, value.var = "BA")[, lapply(.SD, round, 1)]); print(gates)
# ---- (3) Monte Carlo bands ----
VARS <- c("BA", "TPH", "QMD", "HT", "VOL", "RD"); MCF <- function(site) rbindlist(parallel::mclapply(seq_len(nrow(SC)), function(i) { L <- getL(SC$planted[i]); pt <- simx(L$DBH, L$HT, L$EXPF_c, SC$byi[i], SC$planted[i], 100, SC$sdimax[i]); dr <- simplify2array(lapply(seq_len(ND), function(k) onedraw(L$DBH, L$HT, L$EXPF_c, SC$byi[i], SC$planted[i], 100, site)))
  rbindlist(lapply(VARS, function(v) data.table(planted = SC$planted[i], level = SC$level[i], byi = SC$byi[i], sdimax = SC$sdimax[i], site_dev = site, year = 0:100, var = v, point = pt[, v], p05 = apply(dr[, v, ], 1, quantile, .05, na.rm = TRUE), p50 = apply(dr[, v, ], 1, median, na.rm = TRUE), p95 = apply(dr[, v, ], 1, quantile, .95, na.rm = TRUE), n_bad = apply(dr[, v, ], 1, function(x) sum(!is.finite(x)))))) }, mc.cores = NC, mc.set.seed = TRUE))
MC <- rbind(MCF(FALSE), MCF(TRUE)); fwrite(MC, "ms_rdbyi2/scenarios_long_rdbyi2.csv"); cat("\n(3) Monte Carlo 90% bands,", ND, "draws; non-finite values:", sum(MC$n_bad), "\n"); fmt <- function(p, l, h, d = 1) sprintf(paste0("%.", d, "f (%.", d, "f to %.", d, "f)"), p, l, h)
for (sd in c(FALSE, TRUE)) { cat(if (sd) "\nwith a plot-level deviation of SDImax about S1 (a new stand):\n" else "\nSDImax at its S1 prediction (parameter uncertainty only) -- Table 4 values:\n"); t4 <- dcast(MC[site_dev == sd & year %in% c(20, 40, 100)], planted + level + byi + sdimax + year ~ var, value.var = c("point", "p05", "p50", "p95"))
  print(t4[order(planted, byi, year), .(origin = ifelse(planted == 1, "planted", "natural"), BYI = round(byi), SDImax = round(sdimax), year, BA = fmt(point_BA, p05_BA, p95_BA), BA_median = round(p50_BA, 1), QMD = fmt(point_QMD, p05_QMD, p95_QMD), TPH = fmt(point_TPH, p05_TPH, p95_TPH, 0), HT = fmt(point_HT, p05_HT, p95_HT), VOL = fmt(point_VOL, p05_VOL, p95_VOL, 0), RD = fmt(point_RD, p05_RD, p95_RD, 2))]) }
# ---- (4) coverage ----
CV <- rbindlist(parallel::mclapply(seq_along(PI), function(j) { x <- PI[[j]]; hh <- max(x$obs$h); ob <- x$obs[h == hh]; rbindlist(lapply(c(FALSE, TRUE), function(site) { dr <- rbindlist(lapply(seq_len(NDc), function(k) { q <- draw(log(x$byi), x$pl, site); if (!site) q$sm <- q$sm * SMO[[x$p]] / s1p(bs, log(x$byi), x$pl)
      z <- simx(x$L$DBH, x$L$HT, x$L$EXPF_c, x$byi, x$pl, hh, q$sm, q$bg, q$bm, q$R, FT$sigma, FT$delta, q$ph)[hh + 1, ]; ps <- min(max(z[["TPH"]] / x$N0, 0), 1); sb <- rbinom(1, x$n0, ps) / x$n0; data.table(surv = sb, qmd = z[["QMD"]], ba = z[["BA"]] * sb / max(ps, 1e-9)) }))
    data.table(planted = x$pl, h = hh, site_dev = site, var = c("surv", "qmd", "ba"), obs = c(ob$o_surv, ob$o_qmd, ob$o_ba), lo = sapply(dr, quantile, .05, na.rm = TRUE), hi = sapply(dr, quantile, .95, na.rm = TRUE)) })) }, mc.cores = NC, mc.set.seed = TRUE)); CV[, inside := obs >= lo & obs <= hi]; fwrite(CV, "out/coverage_rdbyi2.csv")
cat("\n(4) coverage of the nominal 90% band at each plot's longest horizon,", NDc, "draws; S1 out of fold in the first variant; binomial sampling of survivors included\n"); print(dcast(CV[, .(plots = .N, coverage = round(mean(inside), 3)), by = .(site_dev, var, planted)], site_dev + var ~ planted, value.var = "coverage")); print(CV[, .(plots = .N, coverage = round(mean(inside), 3), mean_width = round(mean(hi - lo), 2)), by = .(site_dev, var)][order(site_dev, var)]); print(CV[, .(plots = .N, coverage = round(mean(inside), 3)), by = .(site_dev, var, long = h >= 10)][order(site_dev, var, long)])
