r <- function(b, x1, x0) exp(b * (log(x1) - log(x0))); cat("\ndiameter growth ratio at fixed RD, 90th over 10th percentile of BYI: natural", round(r(bg[["lbyi"]], byiq[planted == 0, hi], byiq[planted == 0, lo]), 2), "(", paste(round(r(quantile(K[, "e4_lbyi"], c(.025, .975)), byiq[planted == 0, hi], byiq[planted == 0, lo]), 2), collapse = " to "), ")  planted", round(r(bg[["lbyi"]], byiq[planted == 1, hi], byiq[planted == 1, lo]), 2), "(", paste(round(r(quantile(K[, "e4_lbyi"], c(.025, .975)), byiq[planted == 1, hi], byiq[planted == 1, lo]), 2), collapse = " to "), ")\n")
