OR <- c(Natural = "#0072B2", Planted = "#D55E00"); LV <- c(Low = "#56B4E9", Median = "#009E73", High = "#CC79A7"); orig <- function(p) factor(ifelse(p == 1, "Planted", "Natural"), levels = names(OR))
theme_koa <- function() theme_classic(base_size = 9) + theme(axis.text = element_text(colour = "black"), legend.position = "bottom", legend.title = element_blank(), legend.key.size = unit(4, "mm"), plot.tag = element_text(face = "bold", size = 9), strip.background = element_blank(), strip.text = element_text(face = "bold"), plot.margin = margin(3, 5, 3, 3))
band <- function(fun, Mx, grid) { m <- apply(Mx, 1, function(b) fun(b, grid)); data.table(lo = apply(m, 1, quantile, .025, na.rm = TRUE), hi = apply(m, 1, quantile, .975, na.rm = TRUE)) }
g4 <- function(b, d) exp(b[[1]] + b[[2]] * log(d$dbh + 1) + b[[3]] * d$dbh + b[[4]] * d$x + b[[5]] * log(d$byi) + b[[6]] * d$pl); g6 <- function(b, d) 1 - exp(-exp(b[[1]] + b[[2]] * log(d$dbh + 1) + b[[3]] * d$dbh + b[[4]] * d$dbh^2 + b[[5]] * d$bal + b[[6]] * log(d$rd) + b[[7]] * log(d$byi) + b[[8]] * d$pl)); gs <- function(b, d) exp(b[[1]] + b[[2]] * log(d$byi) + b[[3]] * d$pl)
mk <- function(xname, xs, fun, Mx, est) rbindlist(lapply(c(0, 1), function(p) { d <- data.table(dbh = 15, x = 0.25, bal = 10, rd = 0.5, byi = byiq[planted == p, md], pl = p)[rep(1, length(xs))]; d[[xname]] <- xs; cbind(data.table(x = xs, origin = orig(p), y = fun(est, d)), band(fun, Mx, d)) }))
lp <- function(d, xl, yl) ggplot(d, aes(x, y, colour = origin, fill = origin)) + geom_ribbon(aes(ymin = lo, ymax = hi), alpha = 0.25, colour = NA) + geom_line(linewidth = 0.6) + scale_colour_manual(values = OR) + scale_fill_manual(values = OR) + labs(x = xl, y = yl)
