last[, origin := orig(planted)]; bp <- function(o, p, xl, yl, lim) { d <- data.table(o = last[[o]], p = last[[p]], origin = last$origin, h = last$h); mx <- if (is.null(lim)) max(c(d$o, d$p)) * 1.05 else lim
  ggplot(d, aes(p, o)) + annotate("ribbon", x = c(0, mx), ymin = c(0, 0.75 * mx), ymax = c(0, 1.25 * mx), fill = "#56B4E9", alpha = 0.25) + geom_abline(slope = 1, intercept = 0, linewidth = 0.3, colour = "#0072B2") + geom_point(aes(fill = h), shape = 21, size = 1.6, stroke = 0.2) + facet_wrap(~origin) +
    scale_fill_viridis_c(option = "plasma", end = 0.9, name = "Horizon (yr)", limits = range(last$h)) + coord_cartesian(xlim = c(0, mx), ylim = c(0, mx), expand = FALSE) + labs(x = xl, y = yl) }
fig4 <- (bp("o_surv", "p_surv", "Projected survival (proportion)", "Observed survival (proportion)", 1.05) / bp("o_qmd", "p_qmd", "Projected QMD (cm)", "Observed QMD (cm)", NULL) / bp("o_ba", "p_ba", "Projected basal area (m² ha⁻¹)", "Observed basal area (m² ha⁻¹)", NULL)) + plot_layout(guides = "collect") + plot_annotation(tag_levels = "a", tag_prefix = "(", tag_suffix = ")") & theme_koa() & theme(legend.title = element_text(size = 8), legend.key.width = unit(10, "mm"))
