rq <- quantile(FT$s1_resid[planted == 1, r], c(.1, .9)); MULT <- c(central = 1, low = exp(rq[[1]]), high = exp(rq[[2]])); cat("\n(6) workbook grid. Starting list: trees", nrow(L), ", QMD rescaled to 7.24 cm, starting BA-weighted height", round(sum(h0 * d0^2) / sum(d0^2), 2), "m. SDImax multipliers for the low and high cases (10th and 90th percentile of planted plot residuals about S1):", round(MULT[2:3], 3), "\n")
Gd <- rbindlist(lapply(names(MULT), function(sn) rbindlist(lapply(names(SITES), function(s) rbindlist(lapply(DENS, function(n) { sm <- s1p(bs, log(SITES[[s]]), 1) * MULT[[sn]]; z <- as.data.table(simx(d0, h0, L$EXPF_c * n * AC / sum(L$EXPF_c), SITES[[s]], 1, 199, sm)); cbind(sdimax = sn, site = s, byi = SITES[[s]], stems_ac = n, sdimax_value = sm, age = 1:200, z) }))))))
