lg <- function(a, y) { st <- c(A = max(y) * 1.02, B = a[which.min(abs(y - max(y) / 2))], C = 6); o <- optim(st, function(p) sum((y - p[1] / (1 + exp(-(a - p[2]) / p[3])))^2), method = "BFGS", control = list(maxit = 2000, reltol = 1e-12)); o$par }
LG <- Gd[, { p60 <- lg(age[age <= 60], BA_ft2ac[age <= 60]); p100 <- lg(age[age <= 100], BA_ft2ac[age <= 100]); f60 <- p60[1] / (1 + exp(-(age - p60[2]) / p60[3])); f100 <- p100[1] / (1 + exp(-(age - p100[2]) / p100[3]))
  .(A = p60[1], B = p60[2], C = p60[3], rmse = sqrt(mean((BA_ft2ac - f60)[age <= 60]^2)), rmse_pct = 100 * sqrt(mean((BA_ft2ac - f60)[age <= 60]^2)) / mean(BA_ft2ac[age <= 60]), e40 = (BA_ft2ac - f60)[age == 40], e52 = (BA_ft2ac - f60)[age == 52], A100 = p100[1], B100 = p100[2], C100 = p100[3], rmse_pct100 = 100 * sqrt(mean((BA_ft2ac - f100)[age <= 100]^2)) / mean(BA_ft2ac[age <= 100])) }, by = .(sdimax, site, byi, stems_ac)]; fwrite(LG, "out/workbook_logistic_rdbyi2.csv")
DG <- Gd[, .(BA20 = BA_ft2ac[age == 20], BA40 = BA_ft2ac[age == 40], BA52 = BA_ft2ac[age == 52], BA100 = BA_ft2ac[age == 100], BA200 = BA_ft2ac[age == 200], peakBA = max(BA_ft2ac), peak_age = age[which.max(BA_ft2ac)], decline_pct = 100 * (1 - BA_ft2ac[age == 200] / max(BA_ft2ac)), stems52 = TPA[age == 52], qmd52 = QMD_in[age == 52], reineke = coef(lm(log(TPA) ~ log(QMD_in)))[[2]], rises_to_peak = all(diff(BA_ft2ac[age <= age[which.max(BA_ft2ac)]]) >= -1e-9), rd_max = max(RD), sdi_max = max(SDI)), by = .(sdimax, site, byi, stems_ac, sdimax_value)]; fwrite(DG, "out/workbook_diag_rdbyi2.csv")
wc <- dcast(Gd[sdimax == "central"], stems_ac + age ~ site, value.var = "BA_ft2ac"); X8 <- wc[, .(first_inversion = { o <- which(!(`Low Feasibility` <= Marginal + 1e-9 & Marginal <= Good + 1e-9 & Good <= Excellent + 1e-9)); if (length(o)) age[o[1]] else NA_integer_ }, exc_minus_low_100 = (Excellent - `Low Feasibility`)[age == 100], low_minus_exc_200 = (`Low Feasibility` - Excellent)[age == 200]), by = stems_ac]; fwrite(X8, "out/workbook_crossover_rdbyi2.csv")
